            <WrappedComponent
                // eslint-disable-next-line react/jsx-props-no-spreading
                {...(props as TProps)}
                policy={policy}
                policyDraft={policyDraft}
                isLoadingPolicy={isLoadingPolicy}
                ref={ref}
            />
        );
    }

    WithPolicy.displayName = `WithPolicy`;

    return forwardRef(WithPolicy);
